pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        try c.addToBalance{value: amount}() {} catch { return; }
        bool firstReverted;
        uint256 testBefore = address(this).balance;
        try c.withdrawBalance() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        vm.assume(!firstReverted);
        uint256 balAfterFirst;
        try c.getBalance(address(this)) returns (uint256 __r) { balAfterFirst = __r; } catch { return; }
        bool secondReverted;
        uint256 testBeforeSecond = address(this).balance;
        try c.withdrawBalance() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint256 balAfterSecond;
        try c.getBalance(address(this)) returns (uint256 __r) { balAfterSecond = __r; } catch { return; }
        uint256 testAfterSecond = address(this).balance;
        assertTrue(balAfterFirst == 0 &&
            !secondReverted &&
            balAfterSecond == 0 &&
            testAfterSecond == testBeforeSecond);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
